function check(input, actual, expected) {
  const [rows, cols, rCenter, cCenter] = input;
  if (!Array.isArray(actual) || actual.length !== rows * cols) return false;
  const seen = new Set();
  let last = 0;
  for (const cell of actual) {
    if (!Array.isArray(cell) || cell.length !== 2) return false;
    const [r, c] = cell;
    if (!Number.isInteger(r) || !Number.isInteger(c) || r < 0 || r >= rows || c < 0 || c >= cols) return false;
    if (seen.has(r * cols + c)) return false;
    seen.add(r * cols + c);
    const distance = Math.abs(r - rCenter) + Math.abs(c - cCenter);
    if (distance < last) return false;
    last = distance;
  }
  return true;
}

