function validate([rows, cols, rCenter, cCenter]) {
  if (!Number.isInteger(rows) || rows < 1 || rows > 100) return 'rows is a whole number from 1 to 100.';
  if (!Number.isInteger(cols) || cols < 1 || cols > 100) return 'cols is a whole number from 1 to 100.';
  if (!Number.isInteger(rCenter) || rCenter < 0 || rCenter >= rows) return 'rCenter must be a row of the grid.';
  if (!Number.isInteger(cCenter) || cCenter < 0 || cCenter >= cols) return 'cCenter must be a column of the grid.';
  return null;
}

