function allCellsDistOrder(rows, cols, rCenter, cCenter) {
  // Walk outward one distance at a time and collect the cells on each ring.
  const result = [];
  for (let d = 0; d <= rows + cols - 2; d++)
    for (let r = 0; r < rows; r++)
      for (let c = 0; c < cols; c++)
        if (Math.abs(r - rCenter) + Math.abs(c - cCenter) === d) result.push([r, c]);
  return result;
}

